MAP
    NAME "SS_MAP_TRAT_VALVULAS_TRATADA"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_valvulas_agua_tratada.log"
    DEBUG 0
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_TRAT_TAPA_CIEGA"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        STATUS DEFAULT
        INCLUDE 'includes/conexion.map'  
        DATA "geometry from aguatrat_valv using unique gid using srid=32614"
        TYPE POINT
        MINSCALE 1
        MAXSCALE 150000
        CLASSITEM "tipo"
        CLASS
            NAME "tapa ciega"
            EXPRESSION "2"
            STYLE
                SYMBOL "aguaA"
                SIZE 10
                COLOR 0 130 255
                OUTLINECOLOR -1 -1 -1
            END #STYLE
        END #CLASS
        CLASS
            NAME "reduccion"
            EXPRESSION "3"
            STYLE
                SYMBOL "aguaB"
                SIZE 10
                COLOR 0 130 255
                OUTLINECOLOR -1 -1 -1
            END #STYLE
            END #CLASS
            CLASS
            NAME "medidor"
            EXPRESSION "4"
            STYLE
                SYMBOL "aguaC"
                SIZE 10
                COLOR 0 130 255
                OUTLINECOLOR -1 -1 -1
            END #STYLE
        END #CLASS
        CLASS
            NAME "bomba"
            EXPRESSION "5"
            STYLE
                SYMBOL "aguaJ"
                SIZE 10
                COLOR 0 130 255
                OUTLINECOLOR -1 -1 -1
            END #STYLE
        END #CLASS
        CLASS
            NAME "no definido"
            EXPRESSION "20"
            STYLE
                SYMBOL "X"
                SIZE 10
                COLOR 0 130 255
                OUTLINECOLOR -1 -1 -1
            END #STYLE
        END #CLASS
    END #LAYER
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_TRAT_COMPUERTAS_01"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        INCLUDE 'includes/conexion.map'  
        DATA "geometry from (select gid, geometry from aguatrat_valv WHERE tipo = 1 and descripcio = 1) as tmp using unique gid using srid=32614"
        STATUS DEFAULT
        TYPE POINT
        MINSCALE 1
        MAXSCALE 15000
        CLASS
            STYLE
                SYMBOL "aguaD"
                    SIZE 10
                    COLOR 0 130 255
                    OUTLINECOLOR -1 -1 -1
                END #SYMBOL
            END #STYLE
        END #CLASS
    END #LAYER
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_TRAT_MARIPOSA"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        INCLUDE 'includes/conexion.map'  
        DATA "geometry from (select gid, geometry from aguatrat_valv WHERE tipo = 1 and descripcio = 2) as tmp using unique gid using srid=32614"
        STATUS DEFAULT
        TYPE POINT
        MINSCALE 1
        MAXSCALE 15000
        CLASS
            SYMBOL "aguaE"
            SIZE 10
            COLOR 0 130 255
            OUTLINECOLOR -1 -1 -1
        END #CLASS
    END #LAYER
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_TRAT_CONTROL"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        INCLUDE 'includes/conexion.map'  
        DATA "geometry from (select gid, geometry from aguatrat_valv WHERE tipo = 1 and descripcio = 3) as tmp using unique gid using srid=32614"
        TYPE POINT
        MINSCALE 1
        MAXSCALE 15000
        CLASS
            SYMBOL "aguaF"
            SIZE 10
            COLOR 0 130 255
            OUTLINECOLOR -1 -1 -1
        END #CLASS
    END #LAYER
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_TRAT_EXPULSOR_AIRE"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        INCLUDE 'includes/conexion.map'  
        DATA "geometry from (select gid, geometry from aguatrat_valv WHERE tipo = 1 and descripcio = 4) as tmp using unique gid using srid=32614"
        TYPE POINT
        MINSCALE 1
        MAXSCALE 15000
        CLASS
            SYMBOL "aguaG"
            SIZE 10
            COLOR 0 130 255
            OUTLINECOLOR -1 -1 -1
        END #CLASS
    END #LAYER
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_TRAT_COMPUERTAS_02"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        INCLUDE 'includes/conexion.map'  
        DATA "geometry from (select gid, geometry from aguatrat_valv WHERE tipo = 1 and descripcio = 5) as tmp using unique gid using srid=32614"
        STATUS DEFAULT
        TYPE POINT
        MINSCALE 1
        MAXSCALE 15000
        CLASS
            SYMBOL "aguaH"
            SIZE 10
            COLOR 0 130 255
            OUTLINECOLOR -1 -1 -1
        END #CLASS
    END #LAYER
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_TRAT_COMPUERTAS_03"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        INCLUDE 'includes/conexion.map'  
        DATA "geometry from (select gid, geometry from aguatrat_valv WHERE tipo = 1 and descripcio = 6) as tmp using unique gid using srid=32614"
        STATUS DEFAULT
        TYPE POINT
        MINSCALE 1
        MAXSCALE 15000
        CLASS
            SYMBOL "aguaI"
            SIZE 10
            COLOR 0 130 255
            OUTLINECOLOR -1 -1 -1
        END #CLASS
    END #LAYER
END #MAP